StyleSheet:
/* Quiet, borderless Fluent surfaces with restrained elevation. */
.theme { skin: studio; }
.bar { height: 40px; padding: 4px; gap: 3px; border-radius: 10px; border-width: 0px; }
.tab { height: 32px; padding: 0px 14px; margin: 0px; border-radius: 8px; border-width: 0px; font-size: 13px; font-weight: semibold; indicator: underline; selected-background: accent-soft; }
.menu { width: 282px; padding: 10px; gap: 2px; border-radius: 14px; border-width: 0px; box-shadow: 0px 6px 24px rgba(0,0,0,0.2); }
.menu-item { height: 38px; padding: 0px 12px; margin: 0px; border-radius: 8px; border-width: 0px; icon-size: 22px; }
.button { min-height: 34px; padding: 5px 14px; border-radius: 8px; border-width: 0px; font-size: 13px; font-weight: semibold; }
.input { min-height: 34px; padding: 5px 12px; border-radius: 8px; border-width: 0px; }
.card { padding: 18px 20px; gap: 8px; border-radius: 12px; border-width: 0px; box-shadow: 0px 1px 4px rgba(0,0,0,0.06); }
.sidebar-item { height: 38px; padding: 0px 14px; margin: 2px 0px; border-radius: 8px; }
.window { border-radius: 8px; border-width: 1px; }
.titlebar { height: 40px; border-width: 0px; }
.sidebar { border-radius: 0px; border-width: 0px; }
.page { background: transparent; border-width: 0px; }
.toast { border-radius: 12px; border-width: 1px; }
